class Tx {                              // RAII transaction guard: BEGIN in ctor,
    sqlite3* db; bool done = false;     // ROLLBACK in dtor unless commit()
public:
    explicit Tx(sqlite3* d) : db(d) { exec(db, "BEGIN"); }
    ~Tx() { if (!done) exec(db, "ROLLBACK"); }
    void commit() { exec(db, "COMMIT"); done = true; }
};
Tx tx(db);                              // one association update, atomically
for (auto id : added)   stmt(db, "INSERT INTO actor_film VALUES (?,?)", actor_id, id);
for (auto id : removed) stmt(db, "DELETE FROM actor_film WHERE actor_id=? AND film_id=?", actor_id, id);
tx.commit();
